#define nhan43                        \
    ios_base::sync_with_stdio(false); \
    cin.tie(NULL);                    \
    cout.tie(NULL);

void fastIO()
{
    nhan43;
    if (fopen("main.inp", "r"))
    {
        freopen("main.inp", "r", stdin);
        freopen("main.out", "w", stdout);
    }
}

class Solution
{
public:
    void sol()
    {
        long long x, y;
        cin >> x >> y;

        long long k = max(x, y);
        long long base = (k - 1) * (k - 1);

        cout << (k % 2
            ? (x == k ? base + y : base + 2 * k - x)
            : (y == k ? base + x : base + 2 * k - y)
        ) << '\n';
    };
};

int main()
{
    fastIO();
    int tc = 1;
    cin >> tc;
    Solution sol;
    while (tc--)
    {
        sol.sol();
    }
    return 0;
}
